// Prefix Mode Parser Pattern
interface PrefixMode {
  prefix: '!' | '/' | '@' | '&';
  mode: 'bash' | 'command' | 'file' | 'background';
  handler: (input: string) => Promise<void>;
}

const parsePrefixMode = (input: string): { mode: PrefixMode['mode'] | null; content: string } => {
  const prefixMap: Record<string, PrefixMode['mode']> = {
    '!': 'bash',
    '/': 'command',
    '@': 'file',
    '&': 'background'
  };

  const firstChar = input[0];
  if (firstChar in prefixMap) {
    return { mode: prefixMap[firstChar], content: input.slice(1).trim() };
  }
  return { mode: null, content: input };
};
